<script setup lang="ts">
import { Bell, CheckCheck } from 'lucide-vue-next'
definePageMeta({ layout: 'admin', middleware: 'admin-auth' })
const route=useRoute();const workspace=computed(()=>route.path.startsWith('/media')?'media':'media');const notifications=ref<any[]>([]);const unread=ref(0);const pending=ref(true);function date(v:string){return new Date(v).toLocaleString('id-ID',{dateStyle:'medium',timeStyle:'short'})}async function load(){pending.value=true;try{const r=await $fetch<any>('/api/admin/notifications',{query:{workspace:workspace.value}});notifications.value=r.data||[];unread.value=r.unread||0}finally{pending.value=false}}async function markAll(){await $fetch('/api/admin/notifications/read-all',{method:'PATCH',query:{workspace:workspace.value}});await load()}async function mark(n:any){if(n.readAt)return;await $fetch(`/api/admin/notifications/${n.id}`,{method:'PATCH'});n.readAt=new Date().toISOString();unread.value=Math.max(0,unread.value-1)}onMounted(load)
</script>
<template><div><PageHead title="Notifikasi" subtitle="Informasi persisten untuk akun admin"><template #actions><button v-if="unread" class="inline-flex items-center gap-2 rounded-full border border-sht-olive/30 px-4 py-2 text-sm font-semibold text-sht-olive-dark" @click="markAll"><CheckCheck class="h-4 w-4"/>Tandai semua dibaca</button></template></PageHead><section class="mt-6 max-w-3xl overflow-hidden rounded-2xl border border-neutral-line bg-white"><div v-if="pending" class="p-10"><AdminLoadingState/></div><div v-else-if="!notifications.length" class="p-10"><AdminEmptyState title="Belum ada notifikasi"><template #icon><Bell class="h-5 w-5"/></template></AdminEmptyState></div><div v-else><NuxtLink v-for="n in notifications" :key="n.id" :to="n.href||'#'" class="flex gap-3 border-b border-neutral-line p-4 last:border-0 hover:bg-neutral-soft" :class="n.readAt?'text-neutral-charcoal/60':'bg-sht-olive/5'" @click="mark(n)"><span class="mt-1 h-2.5 w-2.5 shrink-0 rounded-full" :class="n.readAt?'bg-neutral-line':'bg-sht-gold'"/><span class="min-w-0 flex-1"><b class="block">{{n.title}}</b><span class="mt-1 block text-sm">{{n.message}}</span><small class="mt-1 block text-xs text-neutral-charcoal/45">{{date(n.createdAt)}}</small></span></NuxtLink></div></section></div></template>
